import { updateRecruitmentAnalyticsSettings, type RecruitmentAnalyticsConfig } from '~/client';

export const useUpdateSettingsAnalytics = defineMutation(() => {
  const queryCache = useQueryCache();
  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (data: RecruitmentAnalyticsConfig): Promise<RecruitmentAnalyticsConfig> =>
      updateRecruitmentAnalyticsSettings({
        composable: '$fetch',
        body: ref(data),
      }),
    onSuccess: () => {
      queryCache.invalidateQueries({ key: ['system-settings'] });
      showToastSuccess('Analytics settings updated successfully');
    },
    onError: (error) => {
      showToastError(error);
    },
  });

  return {
    updateSettingsAnalytics: mutateAsync,
    isUpdateSettingsAnalyticsLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
