<template>
  <Card>
    <CardHeader>
      <CardTitle>Analytics</CardTitle>
    </CardHeader>
    <CardContent>
      <NavigationGuard
        :saved-data="processedPassedData"
        :changed-data="processedDataFromForm"
        title="Warning"
        description="You have some unsaved changes on this tab! Save them before switching to another tab."
        confirm-text="Discard Changes"
      />
      <form id="settingsAnalyticsForm" class="flex flex-col gap-6" @submit="onSubmit">
        <div class="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div class="flex flex-col gap-4">
            <FormItemWrapper
              label="Signup Attribution Window (days)"
              name="signup_attribution_window_days"
              :is-required="true"
              :description="settingsFieldDescriptions.analytics.signup_attribution_window_days"
            >
              <template #default="{ slots }">
                <Input id="signup_attribution_window_days" type="number" min="1" v-bind="slots.componentField" />
              </template>
            </FormItemWrapper>

            <FormItemWrapper
              label="Onboarding-Ready Window (days)"
              name="onboarding_ready_window_days"
              :is-required="true"
              :description="settingsFieldDescriptions.analytics.onboarding_ready_window_days"
            >
              <template #default="{ slots }">
                <Input id="onboarding_ready_window_days" type="number" min="1" v-bind="slots.componentField" />
              </template>
            </FormItemWrapper>

            <FormItemWrapper
              label="Pace Minimum Campaign Age (days)"
              name="pace_min_campaign_age_days"
              :is-required="true"
              :description="settingsFieldDescriptions.analytics.pace_min_campaign_age_days"
            >
              <template #default="{ slots }">
                <Input id="pace_min_campaign_age_days" type="number" min="1" v-bind="slots.componentField" />
              </template>
            </FormItemWrapper>
          </div>

          <div class="flex flex-col gap-4">
            <FormItemWrapper
              label="Unsubscribe Warning Rate"
              name="unsub_warning_rate"
              :is-required="true"
              :description="settingsFieldDescriptions.analytics.unsub_warning_rate"
            >
              <template #default="{ slots }">
                <Input id="unsub_warning_rate" type="number" step="any" v-bind="slots.componentField" />
              </template>
            </FormItemWrapper>

            <FormItemWrapper
              label="Unsubscribe Critical Rate"
              name="unsub_critical_rate"
              :is-required="true"
              :description="settingsFieldDescriptions.analytics.unsub_critical_rate"
            >
              <template #default="{ slots }">
                <Input id="unsub_critical_rate" type="number" step="any" v-bind="slots.componentField" />
              </template>
            </FormItemWrapper>

            <FormItemWrapper
              label="SMS Opt-Out Warning Rate"
              name="sms_opt_out_warning_rate"
              :is-required="true"
              :description="settingsFieldDescriptions.analytics.sms_opt_out_warning_rate"
            >
              <template #default="{ slots }">
                <Input id="sms_opt_out_warning_rate" type="number" step="any" v-bind="slots.componentField" />
              </template>
            </FormItemWrapper>

            <FormItemWrapper
              label="SMS Opt-Out Critical Rate"
              name="sms_opt_out_critical_rate"
              :is-required="true"
              :description="settingsFieldDescriptions.analytics.sms_opt_out_critical_rate"
            >
              <template #default="{ slots }">
                <Input id="sms_opt_out_critical_rate" type="number" step="any" v-bind="slots.componentField" />
              </template>
            </FormItemWrapper>
          </div>
        </div>

        <div class="flex justify-end">
          <Button
            type="submit"
            :loading="isUpdateSettingsAnalyticsLoading"
            :disabled="isEqual(processedDataFromForm, processedPassedData) || isUpdateSettingsAnalyticsLoading"
          >
            Save Analytics Settings
          </Button>
        </div>
      </form>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import { useForm } from 'vee-validate';
import { isEqual } from 'lodash';
import type { GetAllSystemSettingsResponse, RecruitmentAnalyticsConfig } from '~/client';
import { formSchema } from '~/constants/validationSchemas/recruitmentSettingsAnalytics';
import { useUpdateSettingsAnalytics } from '~/mutations/system/updateSettingsAnalytics';
import { settingsFieldDescriptions } from '~/constants/recruitment/settingsFieldDescriptions';

const props = defineProps<{
  settings: GetAllSystemSettingsResponse;
}>();

definePageMeta({
  roles: ['admin'],
});

const { updateSettingsAnalytics, isUpdateSettingsAnalyticsLoading } = useUpdateSettingsAnalytics();

const { handleSubmit, values, resetForm } = useForm({
  validationSchema: formSchema,
  initialValues: {
    signup_attribution_window_days: undefined,
    onboarding_ready_window_days: undefined,
    pace_min_campaign_age_days: undefined,
    unsub_warning_rate: undefined,
    unsub_critical_rate: undefined,
    sms_opt_out_warning_rate: undefined,
    sms_opt_out_critical_rate: undefined,
  },
});

function hydrate(config: RecruitmentAnalyticsConfig) {
  resetForm({
    values: {
      signup_attribution_window_days: config.signup_attribution_window_days,
      onboarding_ready_window_days: config.onboarding_ready_window_days,
      pace_min_campaign_age_days: config.pace_min_campaign_age_days,
      unsub_warning_rate: config.unsub_warning_rate,
      unsub_critical_rate: config.unsub_critical_rate,
      sms_opt_out_warning_rate: config.sms_opt_out_warning_rate,
      sms_opt_out_critical_rate: config.sms_opt_out_critical_rate,
    },
  });
}

onMounted(() => hydrate(props.settings.recruitment_analytics));

const processedPassedData = computed(() => props.settings.recruitment_analytics);

const processedDataFromForm = computed<RecruitmentAnalyticsConfig>(() => ({
  signup_attribution_window_days: toNumberOrNull(values.signup_attribution_window_days) ?? 0,
  onboarding_ready_window_days: toNumberOrNull(values.onboarding_ready_window_days) ?? 0,
  pace_min_campaign_age_days: toNumberOrNull(values.pace_min_campaign_age_days) ?? 0,
  unsub_warning_rate: toNumberOrNull(values.unsub_warning_rate) ?? 0,
  unsub_critical_rate: toNumberOrNull(values.unsub_critical_rate) ?? 0,
  sms_opt_out_warning_rate: toNumberOrNull(values.sms_opt_out_warning_rate) ?? 0,
  sms_opt_out_critical_rate: toNumberOrNull(values.sms_opt_out_critical_rate) ?? 0,
}));

const onSubmit = handleSubmit(async (formValues) => {
  await updateSettingsAnalytics(formValues);
  hydrate(formValues);
});
</script>
