import * as z from 'zod';
import { toTypedSchema } from '@vee-validate/zod';
import { positiveIntPreset } from './utils';

const fractionPreset = (requiredMessage: string) =>
  z.preprocess(
    (val) => (val === '' || val === null || val === undefined ? null : Number(val)),
    z
      .number({ message: requiredMessage })
      .gt(0, { message: 'Must be above 0' })
      .lt(1, { message: 'Must be below 1 - rates are fractions, 0.005 means 0.5%' })
  );

export const schemaObject = {
  signup_attribution_window_days: positiveIntPreset({
    max: 90,
    requiredMessage: 'Signup attribution window is required',
    maxMessage: 'Must be at most 90 days',
    integerMessage: 'Must be a whole number of days',
  }),
  onboarding_ready_window_days: positiveIntPreset({
    max: 180,
    requiredMessage: 'Onboarding-ready window is required',
    maxMessage: 'Must be at most 180 days',
    integerMessage: 'Must be a whole number of days',
  }),
  pace_min_campaign_age_days: positiveIntPreset({
    max: 30,
    requiredMessage: 'Minimum campaign age is required',
    maxMessage: 'Must be at most 30 days',
    integerMessage: 'Must be a whole number of days',
  }),
  unsub_warning_rate: fractionPreset('Unsubscribe warning rate is required'),
  unsub_critical_rate: fractionPreset('Unsubscribe critical rate is required'),
  sms_opt_out_warning_rate: fractionPreset('SMS opt-out warning rate is required'),
  sms_opt_out_critical_rate: fractionPreset('SMS opt-out critical rate is required'),
};

// The API refuses a warning rate at or above its critical rate, so the same rule runs here to put the error on
// the field instead of returning it as a failed save. The dashboard tests the critical rate first, which is what
// makes an inverted pair leave the warning band unreachable.
export const analyticsSchema = z.object(schemaObject).superRefine((data, ctx) => {
  for (const [warningField, criticalField] of [
    ['unsub_warning_rate', 'unsub_critical_rate'],
    ['sms_opt_out_warning_rate', 'sms_opt_out_critical_rate'],
  ] as const) {
    const warning = data[warningField];
    const critical = data[criticalField];
    if (typeof warning !== 'number' || typeof critical !== 'number') continue;
    if (warning >= critical) {
      ctx.addIssue({ code: 'custom', path: [warningField], message: 'Warning rate must be below the critical rate' });
    }
  }
});

export const formSchema = toTypedSchema(analyticsSchema);
